tool_input.content:
const fs=require("fs");
const h=fs.readFileSync("/home/zmhel/gitrepos/learn-ai/eval01/runs/.gen-work/t21/game.html","utf8");
const m=h.match(/<script>([\s\S]*?)<\/script>/);
let src=m[1];
// cut off the UI section (everything from the UI marker) so we can run sim logic headlessly
const cut=src.indexOf("let game = newGame(1337);");
const logic=src.slice(0,cut);
const vm=require("vm");
const ctx={console,performance:{now:()=>Date.now()}};
vm.createContext(ctx);
vm.runInContext(logic+"\n;globalThis.__api={newGame,greedyStep,runTests,runBenchmark,serialize,deserialize,computeScore,RESLIST,GOODLIST,storageCaps,housingCap};",ctx);
const A=ctx.__api;
const g=A.newGame(1337);
const r=A.runTests(g);
for(const a of r.out) console.log((a.ok?"PASS  ":"FAIL  ")+a.name+(a.detail?"   ("+a.detail+")":""));
console.log(r.pass+" passed, "+r.fail+" failed");
const b1=A.runBenchmark(1337,200), b2=A.runBenchmark(1337,200);
console.log("bench hash",b1.hash,b2.hash,b1.hash===b2.hash?"DET-OK":"DET-FAIL");
console.log("bench:",JSON.stringify({turn:b1.turn,pop:b1.pop,res:b1.research,bld:b1.buildings,score:b1.score,alive:b1.alive}));
// playthrough profile
for(const seed of [1337,7,99,2024]){
  const S=A.newGame(seed);
  for(let i=0;i<60&&S.pop.length>0;i++)A.greedyStep(S);
  console.log("seed",seed,"turn",S.turn,"pop",S.pop.length,"res done",A.RESLIST.filter(k=>S.research[k]).length,"over",S.over&&(S.over.win?"WIN":"LOSS"));
}
